import json,re,collections,xml.etree.ElementTree as E
s=json.load(open('source.json')); a=json.load(open('answer.json'))
allowed={'p','br','table','thead','tbody','tfoot','tr','th','td','b','strong','i','em','u','sup','sub','ul','ol','li','div','span','blockquote'}
for source,answer in zip(s,a):
 for k in ['code_id','source_id','source_sha256','number']: assert source[k]==answer[k]
 assert set(answer)=={'code_id','source_id','source_sha256','number','proposed_xml','reason','review_notes','status'}
 assert answer['status']=='rewrite_draft'
 sr=E.fromstring('<r>'+source['source_xml']+'</r>'); pr=E.fromstring('<r>'+answer['proposed_xml']+'</r>')
 for e in pr.iter():
  if e.tag=='r': continue
  assert e.tag in allowed
  for k,v in e.attrib.items(): assert k in ['rowspan','colspan'] and re.fullmatch(r'[0-9]+',v)
 sp=sr.findall('p'); pp=pr.findall('p')
 print('ARTICLE',source['number'],'paragraphes',len(sp),'->',len(pp),'caracteres',len(source['source_xml']),'->',len(answer['proposed_xml']))
 if sp:
  assert len(sp)==len(pp)
  for n,(x,y) in enumerate(zip(sp,pp),1):
   sx=''.join(x.itertext()); px=''.join(y.itertext())
   nums=lambda t:collections.Counter(re.findall(r'\\d+(?:[.,-]\\d+)*',t))
   if nums(sx)"'!=nums(px): print('"'ECART NUMERIQUE P',n,nums(sx)-nums(px),nums(px)-nums(sx))
