   assert (ls.group(1) if ls else None)==(lp.group(1) if lp else None),(n,sx,px)
   if sx==px:print('Alinéa identique',n)
 print('Tableaux',len(sr.findall('.//table')),len(pr.findall('.//table')))
print('Schema et identifiants verifies')
